def receipt_counts(q, include_receipts=False):
    protocol = q.get("protocol", CURRENT_PROTOCOL)
    accepted_for = ACCEPTED_BY_PROTOCOL.get(protocol)
    if accepted_for is None:
        return {"error": "unsupported_protocol"}
    receipts = q.get("receipts", [])
    accepted = accepted_for(receipts)
    response = {
        "protocol": protocol,
        "accepted_count": len(accepted),
        "duplicate_count": len(receipts) - len(accepted),
    }
    if include_receipts:
        response["receipts"] = accepted
    return response

def run(q):
    command = q.get("command")
    if command == "ping":
        return {"status": "ok", "product": "Courier Relay"}
    if command == "accepted":
        return receipt_counts(q, include_receipts=True)
    if command in ("count", "summary"):
        return receipt_counts(q)
    return {"error": "unknown_command"}
